B.Xg=new A.X(B.r,["Nova City. Uma cidade onde humanos e rob\xf4s vivem juntos, em paz... tudo gra\xe7as \xe0 energia do N\xfacleo Nova.","Nova City. A city where humans and robots live together in peace... all thanks to the energy of the Nova Core.","Nova City. Una ciudad donde humanos y robots viven juntos, en paz... todo gracias a la energ\xeda del N\xfacleo Nova."],t.w)
B.apC=new A.ef(null,B.Xg,null)
B.Xe=new A.X(B.r,["Olha s\xf3 esse c\xe9u! Dia perfeito pra treinar. Nada pode estragar isso... n\xe9, Zek?","Look at that sky! A perfect day to train. Nothing can ruin this... right, Zek?","\xa1Mira ese cielo! Un d\xeda perfecto para entrenar. Nada puede arruinarlo... \xbfverdad, Zek?"],t.w)
B.apt=new A.ef("kael",B.Xe,"happy")
B.X5=new A.X(B.r,["Ai, n\xe3o! Por que voc\xea foi falar isso, Kael? Toda vez que algu\xe9m fala isso, d\xe1 tudo errado!","Oh, no! Why did you say that, Kael? Every time someone says that, everything goes wrong!","\xa1Ay, no! \xbfPor qu\xe9 dijiste eso, Kael? \xa1Cada vez que alguien lo dice, todo sale mal!"],t.w)
B.apD=new A.ef("zek",B.X5,"scared")
B.WW=new A.X(B.r,["Relaxa, Zek! O que poderia acontecer?","Relax, Zek! What could possibly happen?","\xa1Tranquilo, Zek! \xbfQu\xe9 podr\xeda pasar?"],t.w)
B.apr=new A.ef("kael",B.WW,"happy")
B.TR=s([B.apC,B.apt,B.apD,B.apr],t.tG)
B.apJ=new A.lQ("intro_1.jpg",1.05,1.18,B.dY,B.dX,B.TR)
B.XC=new A.X(B.r,["Gente... olhem pra cima! O sol... est\xe1 sumindo!","Guys... look up! The sun... is disappearing!","Chicos... \xa1miren arriba! El sol... \xa1est\xe1 desapareciendo!"],t.w)
B.apw=new A.ef("luna",B.XC,"scared")
B.Xv=new A.X(B.r,["Que coisa gigante \xe9 aquela?! Parece um castelo voando!","What is that giant thing?! It looks like a flying castle!","\xbf\xa1Qu\xe9 es esa cosa gigante!? \xa1Parece un castillo volando!"],t.w)
B.apx=new A.ef("mira",B.Xv,"shocked")
B.X3=new A.X(B.r,["Durante o eclipse, uma fortaleza sombria surgiu no c\xe9u: a Cidadela Eclipse.","During the eclipse, a dark fortress rose in the sky: the Eclipse Citadel.","Durante el eclipse, una fortaleza oscura apareci\xf3 en el cielo: la Ciudadela Eclipse."],t.w)
B.apB=new A.ef(null,B.X3,null)
